            {/* Tooltip */}
            {snapInfo && <CursorTooltip text={""} position={snapInfo.position} type={snapInfo.type} />}
            {/* Rotate Gizmo Visualization */}
            {tool === ToolType.ROTATE && rotateState.phase !== 'hover' && rotateState.pivot && (
                <group position={rotateState.pivot}>
                    <mesh rotation={[-Math.PI/2, 0, 0]}>
                        <ringGeometry args={[0.5, 0.55, 32]} />
                        <meshBasicMaterial color="blue" side={THREE.DoubleSide} />
                    </mesh>
                    {rotateState.startVector && (
                         <SimpleLine points={[new THREE.Vector3(), rotateState.startVector.clone().multiplyScalar(2)]} color="blue" />
                    )}
