const ShapeRenderer: React.FC<ShapeRendererProps> = ({ shape, isSelected, pushPullState, pushPullHandlers, drawingHandlers, setDraggingState, onShapeRef }) => {
    const meshRef = useRef<THREE.Mesh>(null);
    const groupRef = useRef<THREE.Group>(null);

    useEffect(() => {
        if (groupRef.current) onShapeRef(shape.id, groupRef.current);
        return () => onShapeRef(shape.id, null);
    }, [shape.id, onShapeRef]);

    const extrudeSettings = useMemo(() => ({
        depth: shape.height,
        bevelEnabled: false
    }), [shape.height]);

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);

    if (shape.type === 'dimension') {
        return <DimensionShape shape={shape} isSelected={isSelected} onSelect={drawingHandlers.handleClick} />;
    }

    if (shape.type === 'line') {
         const points = shape.points.map(p => new THREE.Vector3(p.x, p.y, p.z));
         return (
             <group position={shape.position} rotation={shape.rotation} scale={shape.scale}>
                 <SimpleLine points={points} color={isSelected ? HIGHLIGHT_COLOR : shape.color} />
             </group>
         )
    }

    return (
        <group ref={groupRef} position={shape.position} rotation={shape.rotation} scale={shape.scale}
            onPointerDown={(e) => {
                if (pushPullState.mode !== 'none') pushPullHandlers.handlePointerDown(e);
                else drawingHandlers.handlePointerDown(e);
            }}
            onPointerUp={(e) => {
                 if (pushPullState.mode === 'none') drawingHandlers.handlePointerUp(e);
            }}
            onClick={(e) => {
                 if (pushPullState.mode === 'none') drawingHandlers.handleClick(e);
            }}
        >
             <mesh ref={meshRef} rotation={[Math.PI / 2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, extrudeSettings]} />
                <meshStandardMaterial 
                    color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
                    transparent={shape.type === 'flat'} 
                    opacity={shape.type === 'flat' ? 0.5 : 1}
                />
             </mesh>
             <lineSegments rotation={[Math.PI / 2, 0, 0]}>
                <edgesGeometry args={[new THREE.ExtrudeGeometry(shape2D, extrudeSettings)]} />
                <lineBasicMaterial color={isSelected ? "white" : "black"} />
             </lineSegments>
        </group>
    );
}

