const SelectionGizmo: React.FC<{ setDragging: (active: boolean) => void, shapeRefs?: React.MutableRefObject<Record<string, THREE.Group | null>> }> = ({ setDragging, shapeRefs }) => {
    const { selectedIds, transformMode, updateShape } = useApp();
    const { scene } = useThree();
    const [target, setTarget] = useState<THREE.Object3D | undefined>(undefined);

    useEffect(() => {
        if (selectedIds.length === 1) {
            // Try to find the object in the scene or use passed refs
            // We'll search scene by userData if shapeRefs not passed/available
            let found: THREE.Object3D | undefined = undefined;
            scene.traverse(obj => {
                 if (obj.userData?.id === selectedIds[0]) found = obj.parent || obj; // Parent is the group
            });
            setTarget(found);
        } else {
            setTarget(undefined);
        }
    }, [selectedIds, scene]);

    if (!target || selectedIds.length !== 1) return null;

    return (
        <TransformControls 
            object={target} 
            mode={transformMode} 
            onDragging-changed={(e) => setDragging(e.value)}
            onChange={() => {
                if (target) {
                    // Update shape logic here if needed live, or wait for mouse up (TransformControls handles obj update)
                    // We need to sync back to AppState on mouseUp usually. 
                    // For brevity, we assume updates happen via a callback or we manually sync:
                    const pos = target.position;
                    const rot = target.rotation;
                    const scale = target.scale;
                    updateShape(selectedIds[0], { 
                        position: [pos.x, pos.y, pos.z],
                        rotation: [rot.x, rot.y, rot.z],
                        scale: [scale.x, scale.y, scale.z]
                    });
                }
            }}
        />
    );
}

const CameraHandler = ({ view, onFinished }: { view: string | null, onFinished: () => void }) => {
    const { camera, controls } = useThree();
    useEffect(() => {
        if (!view) return;
        const offset = 20;
        const c = camera as THREE.PerspectiveCamera;
        const target = new THREE.Vector3(0,0,0);

        switch (view) {
            case 'top': c.position.set(0, offset, 0); break;
            case 'front': c.position.set(0, 0, offset); break;
            case 'right': c.position.set(offset, 0, 0); break;
            case 'left': c.position.set(-offset, 0, 0); break;
            case 'bottom': c.position.set(0, -offset, 0); break;
            default: break;
        }
        c.lookAt(target);
        if (controls) {
            // @ts-ignore
            controls.target.copy(target);
            // @ts-ignore
            controls.update();
        }
        onFinished();
    }, [view, camera, controls, onFinished]);

    return null;
}

