import React, { useRef, useState, useMemo, useEffect, useCallback, useLayoutEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, TransformControls, Html, GizmoHelper, GizmoViewport, Text, Billboard } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, IGuideLine } from '../types';
import { SNAP_GRID, HIGHLIGHT_COLOR, DEFAULT_COLOR } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3;

// --- Helper: Get Local Basis Vectors from Normal ---
const getLocalBasis = (normal: THREE.Vector3) => {
    const n = normal.clone().normalize();
    let up = new THREE.Vector3(0, 1, 0);
    if (Math.abs(n.dot(up)) > 0.99) up.set(0, 0, 1);

    const right = new THREE.Vector3().crossVectors(n, up).normalize();
    const top = new THREE.Vector3().crossVectors(right, n).normalize(); 

    return { right, top, normal: n };
};

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';
type AlignmentLine = [THREE.Vector3, THREE.Vector3];

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string;
    snapEdge?: [THREE.Vector3, THREE.Vector3];
    normal?: THREE.Vector3;
}

interface InferenceGuide {
    type: 'x' | 'z';
    start: THREE.Vector3;
    end: THREE.Vector3;
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    dragHeight?: number;
}

interface RotateState {
    phase: 'hover' | 'set-start' | 'rotating';
    pivot: THREE.Vector3 | null;
    axis: THREE.Vector3 | null;
    startVector: THREE.Vector3 | null;
    currentAngle: number;
    initialTransforms: Record<string, { pos: THREE.Vector3, quat: THREE.Quaternion }>;
    lockedAxis: THREE.Vector3 | null;
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
    rotateHandlers: {
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    setDraggingState: (isDragging: boolean) => void;
    onShapeRef: (id: string, ref: THREE.Group | null) => void;
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>;
    setAlignmentLines: (lines: AlignmentLine[]) => void;
}

// --- Geometry Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const v = new THREE.Vector3(localP.x, 0, localP.z);
    v.set(v.x * shape.scale[0], v.y * shape.scale[1], v.z * shape.scale[2]);
    const euler = new THREE.Euler(...shape.rotation);
    v.applyEuler(euler);
    v.add(new THREE.Vector3(...shape.position));
    return v;
};

// Helper: Check if points are effectively the same
const isSamePoint = (p1: IPoint, p2: IPoint) => Math.abs(p1.x - p2.x) < 1e-4 && Math.abs(p1.z - p2.z) < 1e-4;

const getLineEndpoints = (shape: IShape): [THREE.Vector3, THREE.Vector3] | null => {
    if (shape.name !== 'Edge' && shape.type !== 'line') return null;
    if (shape.points.length >= 2) {
        const p1 = transformPoint(shape.points[0], shape);
        const p2 = transformPoint(shape.points[1], shape);
        return [p1, p2];
    }
    return null;
};

const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    ray: THREE.Ray,
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {
    let fallbackSnap: SnapResult;

    // Check for face intersection first
    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;

    if (intersectedObject && shapeData) {
        let normal = new THREE.Vector3(0, 1, 0);
        if (intersectedObject.face) {
            const normalMatrix = new THREE.Matrix3().getNormalMatrix(intersectedObject.object.matrixWorld);
            normal = intersectedObject.face.normal.clone().applyMatrix3(normalMatrix).normalize();
        }
        fallbackSnap = { position: intersectedObject.point, type: 'face', distance: 0, snapObjectId: shapeData.id, normal };
    } else {
        fallbackSnap = {
            position: new THREE.Vector3(Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID, cursorPos.y, Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID),
            type: 'grid', distance: Infinity, normal: new THREE.Vector3(0, 1, 0)
        };
    }

    let bestVertexSnap: SnapResult | null = null;
    let minVertexDist = threshold;

    // Check active points (closing a loop)
    if (activePoints && activePoints.length > 0) {
        const startPt = activePoints[0];
        const ptVec = new THREE.Vector3(startPt.x, startPt.y, startPt.z);
        const dist = ray.distanceToPoint(ptVec);
        if (dist < threshold * 1.5) {
            bestVertexSnap = { position: ptVec, type: 'endpoint', distance: dist, normal: new THREE.Vector3(0,1,0) };
            minVertexDist = dist;
        }
    }

    // Check shape vertices
    for (const shape of shapes) {
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = ray.distanceToPoint(worldPt);
            if (dist < minVertexDist) {
                bestVertexSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id, normal: new THREE.Vector3(0,1,0) };
                minVertexDist = dist;
            }
            if (hasHeight) {
                const worldPtTop = transformPoint(shape.points[i], { ...shape, position: [shape.position[0], shape.position[1] + currentH, shape.position[2]] });
                dist = ray.distanceToPoint(worldPtTop);
                if (dist < minVertexDist) {
                    bestVertexSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id, normal: new THREE.Vector3(0,1,0) };
                    minVertexDist = dist;
                }
            }
        }
    }

    if (bestVertexSnap) return bestVertexSnap;
    return fallbackSnap;
};

// --- Components ---

const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)));
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);
    useLayoutEffect(() => {
        if (dashed && ref.current) ref.current.computeLineDistances();
    }, [geometry, dashed]);
    return (
        <line ref={ref as any} geometry={geometry}>
            {dashed ? ( <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} /> ) : ( <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} /> )}
        </line>
    );
};

const InferenceGuideRenderer: React.FC<{ guide: InferenceGuide | null }> = ({ guide }) => {
    if (!guide) return null;
    const color = guide.type === 'x' ? '#ef4444' : '#22c55e'; // Red for X, Green for Z
    return (
         <SimpleLine 
            points={[guide.start, guide.end]} 
            color={color} 
            lineWidth={2} 
            depthTest={false} 
            opacity={0.8} 
        />
    );
};

const GuideLinesRenderer: React.FC<{ lines: IGuideLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return (
        <group renderOrder={9999}>
            {lines.map((line) => {
                const p1 = new THREE.Vector3(...line.points[0]);
                const p2 = new THREE.Vector3(...line.points[1]);
                const dir = new THREE.Vector3().subVectors(p2, p1).normalize();
                const start = p1.clone().add(dir.clone().multiplyScalar(-1000));
                const end = p1.clone().add(dir.clone().multiplyScalar(1000));
                return (
                    <SimpleLine 
                        key={line.id} 
                        points={[start, end]} 
                        color="#a855f7" 
                        dashed 
                        lineWidth={1} 
                        depthTest={false} 
                        opacity={0.8} 
                    />
                );
            })}
        </group>
    );
};

const DimensionShape: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
    const { formatValue, tool, updateShape } = useApp();
    const { camera, gl } = useThree();
    const [dragP3, setDragP3] = useState<THREE.Vector3 | null>(null);
    const draggingRef = useRef(false);

    if (!shape.points || shape.points.length < 3) return null;

    const p1 = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
    const p2 = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
    const p3Source = dragP3 || new THREE.Vector3(shape.points[2].x, shape.points[2].y, shape.points[2].z);

    const v12 = new THREE.Vector3().subVectors(p2, p1);
    const v13 = new THREE.Vector3().subVectors(p3Source, p1);
    const projection = v13.dot(v12) / v12.lengthSq();
    const projectedPoint = p1.clone().add(v12.multiplyScalar(projection));
    const offsetVector = new THREE.Vector3().subVectors(p3Source, projectedPoint);

    const dimStart = p1.clone().add(offsetVector);
    const dimEnd = p2.clone().add(offsetVector);
    const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);

    const color = isSelected ? '#3b82f6' : (shape.color || '#333');

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT && isSelected && e.button === 0) {
            e.stopPropagation();
            draggingRef.current = true;
            document.body.style.cursor = 'grabbing';
            const handleWindowMove = (ev: PointerEvent) => {
                if (!draggingRef.current) return;
                const raycaster = new THREE.Raycaster();
                const ndc = new THREE.Vector2((ev.clientX / gl.domElement.clientWidth) * 2 - 1, -(ev.clientY / gl.domElement.clientHeight) * 2 + 1);
                raycaster.setFromCamera(ndc, camera);
                const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -p1.y);
                const target = new THREE.Vector3();
                if (raycaster.ray.intersectPlane(plane, target)) setDragP3(target);
            };
            const handleWindowUp = () => {
                if (draggingRef.current) {
                    draggingRef.current = false;
                    document.body.style.cursor = 'default';
                    window.removeEventListener('pointermove', handleWindowMove);
                    window.removeEventListener('pointerup', handleWindowUp);
                    setDragP3((finalP3) => {
                        if (finalP3) {
                            const newPoints = [shape.points[0], shape.points[1], { x: finalP3.x, y: finalP3.y, z: finalP3.z }];
                            updateShape(shape.id, { points: newPoints });
                        }
                        return null;
                    });
                }
            };
            window.addEventListener('pointermove', handleWindowMove);
            window.addEventListener('pointerup', handleWindowUp);
        } else {
            e.stopPropagation();
            onSelect(e);
        }
    };

    return (
        <group onPointerDown={handlePointerDown} position={shape.position} rotation={shape.rotation} scale={shape.scale}>
            <SimpleLine points={[dimStart, dimEnd]} color={color} depthTest={false} />
            <SimpleLine points={[p1, dimStart]} color="#999" dashed depthTest={false} />
            <SimpleLine points={[p2, dimEnd]} color="#999" dashed depthTest={false} />
            <mesh position={dimStart}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>
            <mesh position={dimEnd}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>
            <Billboard position={midPoint}>
                <Text fontSize={0.25} color={color} anchorX="center" anchorY="middle" outlineWidth={0.02} outlineColor="#ffffff" depthTest={false} renderOrder={1000}>
                    {formatValue(p1.distanceTo(p2))}
                </Text>
            </Billboard>
        </group>
    );
};

const MemoizedOrbitControls = React.memo(({ tool }: { tool: ToolType }) => {
    const ref = useRef<any>(null);
    useEffect(() => {
        if (ref.current) {
            const isDrawing = [ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DIMENSION, ToolType.MEASURE].includes(tool);
            // Left mouse rotates if NOT drawing. Right mouse always pans. Middle rotates.
            ref.current.mouseButtons = {
                LEFT: isDrawing ? null : THREE.MOUSE.ROTATE,
                MIDDLE: THREE.MOUSE.ROTATE,
                RIGHT: THREE.MOUSE.PAN
            };
            ref.current.update();
        }
    }, [tool]);
    return <OrbitControls ref={ref} makeDefault minDistance={0.5} maxDistance={100} dampingFactor={0.1} enableDamping={true} rotateSpeed={0.5} panSpeed={0.6} zoomSpeed={0.8} zoomToCursor={true} />;
});

// --- Shape Renderer ---

const ShapeRenderer: React.FC<ShapeRendererProps> = ({ shape, isSelected, pushPullState, pushPullHandlers, drawingHandlers, rotateHandlers, setDraggingState, onShapeRef }) => {
    const meshRef = useRef<THREE.Mesh>(null);
    const groupRef = useRef<THREE.Group>(null);
    const { tool, selectShape } = useApp();

    useEffect(() => {
        if (groupRef.current) onShapeRef(shape.id, groupRef.current);
        return () => onShapeRef(shape.id, null);
    }, [shape.id, onShapeRef]);

    const isPushPullMode = tool === ToolType.PUSH_PULL;

    // Calculate drag scale for push/pull preview
    let scaleY = 1;
    const isDraggingTop = pushPullState.mode === 'top' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) {
        scaleY = pushPullState.dragHeight / shape.height;
    }

    if (shape.type === 'dimension') return <DimensionShape shape={shape} isSelected={isSelected} onSelect={drawingHandlers.handleClick} />;

    if (shape.type === 'line') {
         const points = shape.points.map(p => new THREE.Vector3(p.x, p.y, p.z));
         return (
             <group 
                position={shape.position} rotation={shape.rotation} scale={shape.scale}
                onClick={(e) => { e.stopPropagation(); selectShape(shape.id, e.ctrlKey); }}
             >
                 <SimpleLine points={points} color={isSelected ? HIGHLIGHT_COLOR : shape.color} />
             </group>
         );
    }

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);
    const extrudeSettings = useMemo(() => ({ depth: shape.height, bevelEnabled: false }), [shape.height]);

    return (
        <group ref={groupRef} position={shape.position} rotation={shape.rotation} scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]}
            onPointerDown={(e) => {
                if (isPushPullMode) pushPullHandlers.handlePointerDown(e);
                else if (tool === ToolType.ROTATE) rotateHandlers.handleClick(e);
                else if (tool === ToolType.SELECT) { e.stopPropagation(); selectShape(shape.id, e.ctrlKey); }
                else drawingHandlers.handlePointerDown(e);
            }}
            onPointerMove={(e) => { if (isPushPullMode) pushPullHandlers.handlePointerMove(e); }}
            onPointerUp={(e) => { if (isPushPullMode) pushPullHandlers.handlePointerUp(); }}
        >
             <mesh ref={meshRef} rotation={[Math.PI / 2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, extrudeSettings]} />
                <meshStandardMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} transparent={shape.type === 'flat'} opacity={shape.type === 'flat' ? 0.5 : 1} />
             </mesh>
             <lineSegments rotation={[Math.PI / 2, 0, 0]}>
                <edgesGeometry args={[new THREE.ExtrudeGeometry(shape2D, extrudeSettings)]} />
                <lineBasicMaterial color={isSelected ? "white" : "black"} />
             </lineSegments>
        </group>
    );
};

// --- Drawing Preview & Interaction Layer ---

const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3; drawingNormal: THREE.Vector3 }> = ({ tool, points, cursorPos, drawingNormal }) => {
    const { formatValue } = useApp();
    if (points.length === 0) return null;

    const start = points[points.length - 1];
    const startVec = new THREE.Vector3(start.x, start.y, start.z);

    if (tool === ToolType.DRAW_LINE) {
        // Show full path history + current line
        const historyPoints = points.map(p => new THREE.Vector3(p.x, p.y, p.z));
        return (
            <group>
                <SimpleLine points={[...historyPoints, cursorPos]} color="#3b82f6" />
                <Billboard position={cursorPos}>
                    <Text fontSize={0.25} color="#3b82f6" anchorX="center" anchorY="bottom">{formatValue(startVec.distanceTo(cursorPos))}</Text>
                </Billboard>
            </group>
        );
    }

    if (tool === ToolType.DRAW_RECT && points.length === 1) {
        const { right, top } = getLocalBasis(drawingNormal);
        const diff = new THREE.Vector3().subVectors(cursorPos, startVec);
        const w = diff.dot(right);
        const h = diff.dot(top);

        const p1 = startVec;
        const p2 = startVec.clone().add(right.clone().multiplyScalar(w));
        const p3 = startVec.clone().add(right.clone().multiplyScalar(w)).add(top.clone().multiplyScalar(h));
        const p4 = startVec.clone().add(top.clone().multiplyScalar(h));

        return (
            <group>
                <SimpleLine points={[p1, p2, p3, p4, p1]} color="#3b82f6" />
                <Billboard position={p3}>
                    <Text fontSize={0.25} color="#3b82f6" anchorX="left" anchorY="bottom">{`${formatValue(Math.abs(w))} x ${formatValue(Math.abs(h))}`}</Text>
                </Billboard>
            </group>
        );
    }

    if (tool === ToolType.DRAW_CIRCLE && points.length === 1) {
        const radius = startVec.distanceTo(cursorPos);
        const circlePts = createCirclePoints(radius).map(p => new THREE.Vector3(p.x + startVec.x, p.y + startVec.y, p.z + startVec.z));
        return (
            <group>
                <SimpleLine points={circlePts} color="#3b82f6" />
                <SimpleLine points={[startVec, cursorPos]} color="#999" dashed />
                <Billboard position={cursorPos}>
                    <Text fontSize={0.25} color="#3b82f6" anchorX="center" anchorY="bottom">R: {formatValue(radius)}</Text>
                </Billboard>
            </group>
        );
    }

    return null;
};

const InteractionLayer: React.FC<{ 
    tool: ToolType, 
    cursorPos: THREE.Vector3,
    snapInfo: SnapResult | null,
    drawPoints: IPoint[],
    inferenceGuide: InferenceGuide | null,
    drawingNormal: THREE.Vector3
}> = ({ drawPoints, cursorPos, snapInfo, inferenceGuide, tool, drawingNormal }) => {
    return (
        <group>
            <DrawingPreview tool={tool} points={drawPoints} cursorPos={cursorPos} drawingNormal={drawingNormal} />

            {snapInfo && snapInfo.type !== 'grid' && snapInfo.type !== 'none' && (
                <mesh position={snapInfo.position}>
                    <sphereGeometry args={[0.08]} />
                    <meshBasicMaterial color={snapInfo.type === 'endpoint' || snapInfo.type === 'vertex' ? '#22c55e' : '#f59e0b'} depthTest={false} />
                </mesh>
            )}

            <InferenceGuideRenderer guide={inferenceGuide} />
        </group>
    );
};

const AlignmentLinesRenderer: React.FC<{ lines: AlignmentLine[] }> = ({ lines }) => {
    return <group>{lines.map((line, idx) => <SimpleLine key={idx} points={line} color="pink" dashed />)}</group>;
};

const SelectionGizmo: React.FC<{ setDragging: (active: boolean) => void }> = ({ setDragging }) => {
    const { selectedIds, transformMode, updateShape } = useApp();
    const { scene } = useThree();
    const [target, setTarget] = useState<THREE.Object3D | undefined>(undefined);

    useFrame(() => {
        if (selectedIds.length === 1) {
            let found: THREE.Object3D | undefined = undefined;
            scene.traverse(obj => { if (obj.userData?.id === selectedIds[0]) found = obj.parent || obj; });
            if (found !== target) setTarget(found);
        } else if (target) {
            setTarget(undefined);
        }
    });

    if (!target) return null;

    return (
        <TransformControls 
            object={target} 
            mode={transformMode} 
            onDragging-changed={(e) => setDragging(e.value)}
            onMouseUp={() => {
                if (target) {
                    const { position, rotation, scale } = target;
                    updateShape(selectedIds[0], { 
                        position: [position.x, position.y, position.z],
                        rotation: [rotation.x, rotation.y, rotation.z],
                        scale: [scale.x, scale.y, scale.z]
                    });
                }
            }}
        />
    );
};

const CameraHandler = ({ view, onFinished }: { view: string | null, onFinished: () => void }) => {
    const { camera, controls } = useThree();
    useEffect(() => {
        if (!view) return;
        const offset = 20;
        const c = camera as THREE.PerspectiveCamera;
        const target = new THREE.Vector3(0,0,0);
        switch (view) {
            case 'top': c.position.set(0, offset, 0); break;
            case 'front': c.position.set(0, 0, offset); break;
            case 'right': c.position.set(offset, 0, 0); break;
            case 'left': c.position.set(-offset, 0, 0); break;
            case 'bottom': c.position.set(0, -offset, 0); break;
            default: break;
        }
        c.lookAt(target);
        if (controls) {
            // @ts-ignore
            controls.target.copy(target);
            // @ts-ignore
            controls.update();
        }
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

// --- HOOKS ---

const usePushPullManager = () => {
    const { shapes, updateShape, tool } = useApp();
    const { camera, gl } = useThree();
    const [ppState, setPpState] = useState<PushPullState>({ mode: 'none', hoveredShapeId: null, dragStartPoint: null, originalHeight: 0 });

    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;
        if (ppState.dragStartPoint && ppState.hoveredShapeId) {
             const raycaster = new THREE.Raycaster();
             const ndc = new THREE.Vector2((e.nativeEvent.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.nativeEvent.clientY / gl.domElement.clientHeight) * 2 + 1);
             raycaster.setFromCamera(ndc, camera);
             const plane = new THREE.Plane();
             plane.setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()), ppState.dragStartPoint);
             const target = new THREE.Vector3();
             raycaster.ray.intersectPlane(plane, target);
             if (target) {
                 const deltaY = target.y - ppState.dragStartPoint.y;
                 const newHeight = Math.max(0.01, ppState.originalHeight + deltaY);
                 setPpState(prev => ({ ...prev, dragHeight: newHeight }));
                 updateShape(ppState.hoveredShapeId!, { height: newHeight });
             }
        } else {
            const intersect = e.intersections.find(i => i.object.userData?.isShape);
            if (intersect) {
                setPpState({ mode: 'top', hoveredShapeId: intersect.object.userData.id, dragStartPoint: null, originalHeight: 0 });
                document.body.style.cursor = 'ns-resize';
            } else {
                setPpState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
                document.body.style.cursor = 'default';
            }
        }
    }, [tool, ppState, shapes, camera, gl, updateShape]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || !ppState.hoveredShapeId || e.button !== 0) return;
        e.stopPropagation();
        const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
        if (shape) {
            setPpState(prev => ({ ...prev, dragStartPoint: e.point.clone(), originalHeight: shape.height }));
        }
    }, [tool, ppState.hoveredShapeId, shapes]);

    const handlePointerUp = useCallback(() => {
        if (ppState.dragStartPoint) setPpState(prev => ({ ...prev, dragStartPoint: null, dragHeight: undefined }));
    }, [ppState.dragStartPoint]);

    return { ppState, handlePointerMove, handlePointerDown, handlePointerUp };
};

const useRotateManager = () => {
    const { tool, selectedIds, updateShape, shapes } = useApp();
    const [rotateState, setRotateState] = useState<RotateState>({
        phase: 'hover', pivot: null, axis: null, startVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis: null
    });

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (tool !== ToolType.ROTATE || selectedIds.length === 0 || e.button !== 0) return;

        if (rotateState.phase === 'hover') {
            const pivot = e.point.clone();
            const initialTransforms: Record<string, { pos: THREE.Vector3, quat: THREE.Quaternion }> = {};
            selectedIds.forEach(id => {
                const shape = shapes.find(s => s.id === id);
                if (shape) {
                    initialTransforms[id] = { 
                        pos: new THREE.Vector3(...shape.position), 
                        quat: new THREE.Quaternion().setFromEuler(new THREE.Euler(...shape.rotation)) 
                    };
                }
            });
            setRotateState(prev => ({ ...prev, phase: 'set-start', pivot, initialTransforms }));
        } else if (rotateState.phase === 'set-start') {
            const startVec = e.point.clone().sub(rotateState.pivot!).normalize();
            setRotateState(prev => ({ ...prev, phase: 'rotating', startVector: startVec }));
        } else if (rotateState.phase === 'rotating') {
            setRotateState({ phase: 'hover', pivot: null, axis: null, startVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis: null });
        }
    }, [tool, selectedIds, rotateState, shapes]);

    const handleRotateMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.ROTATE || rotateState.phase !== 'rotating') return;
        const currentVec = e.point.clone().sub(rotateState.pivot!).normalize();
        let angle = rotateState.startVector!.angleTo(currentVec);
        const cross = new THREE.Vector3().crossVectors(rotateState.startVector!, currentVec);
        if (cross.y < 0) angle = -angle;

        selectedIds.forEach(id => {
            const init = rotateState.initialTransforms[id];
            if (!init) return;
            const relativePos = init.pos.clone().sub(rotateState.pivot!);
            relativePos.applyAxisAngle(new THREE.Vector3(0, 1, 0), angle);
            const newPos = rotateState.pivot!.clone().add(relativePos);
            const q = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), angle);
            const newQuat = init.quat.clone().multiply(q);
            const newEuler = new THREE.Euler().setFromQuaternion(newQuat);
            updateShape(id, { position: [newPos.x, newPos.y, newPos.z], rotation: [newEuler.x, newEuler.y, newEuler.z] });
        });
    }, [tool, rotateState, selectedIds, updateShape]);

    return { rotateState, handleClick, handleRotateMove };
};

const useDrawingManager = () => {
    const { tool, addShape, shapes } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [inferenceGuide, setInferenceGuide] = useState<InferenceGuide | null>(null);

    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        const intersect = e.intersections.find(i => i.object.userData?.isShape);
        const snap = getGeometrySnap(e.point, e.ray, shapes, drawPoints, SNAP_THRESHOLD, intersect);
        setCursorPos(snap.position);
        setSnapInfo(snap);
    }, [shapes, drawPoints]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        // Only draw on Left Click
        if (e.button !== 0) return;

        // Prevent drawing if we clicked on a Gizmo or other interactive element
        // (Handled by checking tool type mostly, but stopPropagation helps)

        if (![ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DIMENSION, ToolType.MEASURE].includes(tool)) return;

        e.stopPropagation();
        const p = snapInfo ? snapInfo.position : e.point;
        const newPoint = { x: p.x, y: 0, z: p.z };

        if (tool === ToolType.DRAW_LINE) {
            const newPoints = [...drawPoints, newPoint];
            setDrawPoints(newPoints);
            // Finish line if clicking back on start (roughly)
            if (drawPoints.length > 2 && snapInfo?.type === 'endpoint' && isSamePoint(newPoint, drawPoints[0])) {
                 addShape({ id: `poly-${Date.now()}`, type: 'solid', points: newPoints.slice(0, -1), height: 3, color: DEFAULT_COLOR, position: [0,0,0], rotation: [0,0,0], scale: [1,1,1], name: 'Poly', layerId: 'layer-structure' });
                 setDrawPoints([]);
            }
        } else if (tool === ToolType.DRAW_RECT) {
            if (drawPoints.length === 0) {
                setDrawPoints([newPoint]);
            } else {
                const start = drawPoints[0];
                const width = newPoint.x - start.x;
                const depth = newPoint.z - start.z;
                const pts = [{ x: 0, y: 0, z: 0 }, { x: width, y: 0, z: 0 }, { x: width, y: 0, z: depth }, { x: 0, y: 0, z: depth }];
                addShape({ id: `rect-${Date.now()}`, type: 'solid', points: pts, height: 0.1, color: DEFAULT_COLOR, position: [start.x, 0, start.z], rotation: [0,0,0], scale: [1,1,1], name: 'Rect', layerId: 'layer-structure' });
                setDrawPoints([]);
            }
        } else if (tool === ToolType.DRAW_CIRCLE) {
            if (drawPoints.length === 0) {
                setDrawPoints([newPoint]);
            } else {
                const center = drawPoints[0];
                const radius = Math.sqrt(Math.pow(newPoint.x - center.x, 2) + Math.pow(newPoint.z - center.z, 2));
                const pts = createCirclePoints(radius);
                addShape({ id: `circle-${Date.now()}`, type: 'solid', points: pts, height: 0.1, color: DEFAULT_COLOR, position: [center.x, 0, center.z], rotation: [0,0,0], scale: [1,1,1], name: 'Circle', layerId: 'layer-structure' });
                setDrawPoints([]);
            }
        }
    }, [tool, snapInfo, drawPoints, addShape]);

    return { 
        drawPoints, cursorPos, setCursorPos, snapInfo, setSnapInfo, inferenceGuide, setInferenceGuide, 
        handlePointerDown, handlePointerUp: () => {}, handleClick: handlePointerDown, handlePointerMove 
    };
};

const useBoxSelection = ({ onBoxChange }: { onBoxChange: (box: { left: number, top: number, width: number, height: number } | null) => void }) => {
    const { tool } = useApp();
    const { gl } = useThree();
    const [startPos, setStartPos] = useState<{x: number, y: number} | null>(null);

    useEffect(() => {
        if (tool !== ToolType.SELECT) return;
        const canvas = gl.domElement;
        const onDown = (e: PointerEvent) => {
            if (e.button !== 0 || e.ctrlKey) return;
            const rect = canvas.getBoundingClientRect();
            setStartPos({ x: e.clientX - rect.left, y: e.clientY - rect.top });
        };
        const onMove = (e: PointerEvent) => {
            if (!startPos) return;
            const rect = canvas.getBoundingClientRect();
            const currentX = e.clientX - rect.left;
            const currentY = e.clientY - rect.top;
            onBoxChange({ left: Math.min(startPos.x, currentX), top: Math.min(startPos.y, currentY), width: Math.abs(currentX - startPos.x), height: Math.abs(currentY - startPos.y) });
        };
        const onUp = () => {
            if (startPos) { onBoxChange(null); setStartPos(null); }
        };
        canvas.addEventListener('pointerdown', onDown);
        window.addEventListener('pointermove', onMove);
        window.addEventListener('pointerup', onUp);
        return () => {
            canvas.removeEventListener('pointerdown', onDown);
            window.removeEventListener('pointermove', onMove);
            window.removeEventListener('pointerup', onUp);
        };
    }, [tool, startPos, gl.domElement, onBoxChange]);

    return { onPointerDown: () => {} };
};

// --- Main Component ---

const EditorContent: React.FC<{ onSelectionBoxUpdate: (box: { left: number, top: number, width: number, height: number } | null) => void }> = ({ onSelectionBoxUpdate }) => {
  const { shapes, tool, selectedIds, selectShape, updateShapes, guideLines, currentView, setCurrentView } = useApp();
  const [alignmentLines, setAlignmentLines] = useState<AlignmentLine[]>([]);
  const shapeRefs = useRef<Record<string, THREE.Group | null>>({});
  const [isGizmoDragging, setIsGizmoDragging] = useState(false);

  const setShapeRef = useCallback((id: string, ref: THREE.Group | null) => { shapeRefs.current[id] = ref; }, []);

  const { ppState, handlePointerMove: handlePPMove, handlePointerDown: handlePPDown, handlePointerUp: handlePPUp } = usePushPullManager();
  const { rotateState, handleRotateMove, handleClick: handleRotateClick } = useRotateManager();
  const { drawPoints, cursorPos: drawCursorPos, snapInfo: drawSnapInfo, handlePointerDown: handleDrawDown, handlePointerMove: handleDrawMove, inferenceGuide } = useDrawingManager();

  const { onPointerDown: onBoxDown } = useBoxSelection({ onBoxChange: onSelectionBoxUpdate });

  const pushPullHandlers = useMemo(() => ({ handlePointerDown: handlePPDown, handlePointerUp: handlePPUp, handlePointerMove: handlePPMove }), [handlePPDown, handlePPUp, handlePPMove]);
  const drawingHandlers = useMemo(() => ({ handlePointerDown: handleDrawDown, handlePointerUp: () => {}, handleClick: () => {} }), [handleDrawDown]);
  const rotateHandlers = useMemo(() => ({ handleClick: handleRotateClick, handlePointerMove: handleRotateMove }), [handleRotateClick, handleRotateMove]);

  return (
    <>
        <ambientLight intensity={0.7} />
        <directionalLight position={[10, 20, 10]} intensity={1.2} castShadow shadow-mapSize={[2048, 2048]} />
        <Grid infiniteGrid fadeDistance={50} sectionColor="#cbd5e1" cellColor="#e2e8f0" sectionSize={1} cellSize={0.1} />

        <MemoizedOrbitControls tool={tool} />

        <group 
            onPointerDown={(e) => {
                if (tool === ToolType.ROTATE) handleRotateClick(e);
                else if (tool === ToolType.SELECT) { onBoxDown(e); selectShape('', false); }
                else if (tool !== ToolType.PUSH_PULL) handleDrawDown(e);
            }} 
            onPointerUp={(e) => { if (tool === ToolType.PUSH_PULL) handlePPUp(); }}
            onPointerMove={(e) => { 
                if (tool === ToolType.PUSH_PULL) handlePPMove(e); 
                else if (tool === ToolType.ROTATE) handleRotateMove(e);
                else handleDrawMove(e);
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, -0.02, 0]} receiveShadow><planeGeometry args={[1000, 1000]} /><meshBasicMaterial visible={false} /></mesh>
        </group>

        <group>
          {shapes.map(shape => (
            <ShapeRenderer
              key={shape.id}
              shape={shape}
              isSelected={selectedIds.includes(shape.id)}
              pushPullState={ppState}
              pushPullHandlers={pushPullHandlers}
              drawingHandlers={drawingHandlers}
              rotateHandlers={rotateHandlers}
              setDraggingState={() => {}}
              onShapeRef={setShapeRef}
              shapeRefs={shapeRefs}
              setAlignmentLines={setAlignmentLines}
            />
          ))}
        </group>

        <InteractionLayer tool={tool} cursorPos={drawCursorPos} snapInfo={drawSnapInfo} drawPoints={drawPoints} inferenceGuide={inferenceGuide} drawingNormal={new THREE.Vector3(0,1,0)} />
        <AlignmentLinesRenderer lines={alignmentLines} />
        <GuideLinesRenderer lines={guideLines} />

        { !isGizmoDragging && <SelectionGizmo setDragging={setIsGizmoDragging} /> }
        { isGizmoDragging && <SelectionGizmo setDragging={setIsGizmoDragging} /> }

        <GizmoHelper alignment="bottom-left" margin={[80, 80]}><GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="white" /></GizmoHelper>
        <CameraHandler view={currentView} onFinished={() => setCurrentView(null)} />
    </>
  );
};

const Viewport: React.FC = () => {
  const { tool } = useApp();
  const [selectionBox, setSelectionBox] = useState<{ left: number, top: number, width: number, height: number } | null>(null);

