const SelectionGizmo: React.FC<{ setDragging: (active: boolean) => void }> = ({ setDragging }) => {
    const { selectedIds, transformMode, updateShape } = useApp();
    const { scene } = useThree();
    const [target, setTarget] = useState<THREE.Object3D | undefined>(undefined);

    useFrame(() => {
        if (selectedIds.length === 1) {
            let found: THREE.Object3D | undefined = undefined;
            scene.traverse(obj => { if (obj.userData?.id === selectedIds[0]) found = obj.parent || obj; });
            if (found !== target) setTarget(found);
        } else if (target) {
            setTarget(undefined);
        }
    });

    if (!target) return null;

    return (
        <TransformControls 
            object={target} 
            mode={transformMode} 
            onDragging-changed={(e) => setDragging(e.value)}
            onMouseUp={() => {
                if (target) {
                    const { position, rotation, scale } = target;
                    updateShape(selectedIds[0], { 
                        position: [position.x, position.y, position.z],
                        rotation: [rotation.x, rotation.y, rotation.z],
                        scale: [scale.x, scale.y, scale.z]
                    });
                }
            }}
        />
    );
};

const CameraHandler = ({ view, onFinished }: { view: string | null, onFinished: () => void }) => {
    const { camera, controls } = useThree();
    useEffect(() => {
        if (!view) return;
        const offset = 20;
        const c = camera as THREE.PerspectiveCamera;
        const target = new THREE.Vector3(0,0,0);
        switch (view) {
            case 'top': c.position.set(0, offset, 0); break;
            case 'front': c.position.set(0, 0, offset); break;
            case 'right': c.position.set(offset, 0, 0); break;
            case 'left': c.position.set(-offset, 0, 0); break;
            case 'bottom': c.position.set(0, -offset, 0); break;
            default: break;
        }
        c.lookAt(target);
        if (controls) {
            // @ts-ignore
            controls.target.copy(target);
            // @ts-ignore
            controls.update();
        }
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

// --- HOOKS ---

const usePushPullManager = () => {
    const { shapes, updateShape, tool } = useApp();
    const { camera, gl } = useThree();
    const [ppState, setPpState] = useState<PushPullState>({ mode: 'none', hoveredShapeId: null, dragStartPoint: null, originalHeight: 0 });

    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;
        if (ppState.dragStartPoint && ppState.hoveredShapeId) {
             const raycaster = new THREE.Raycaster();
             const ndc = new THREE.Vector2((e.nativeEvent.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.nativeEvent.clientY / gl.domElement.clientHeight) * 2 + 1);
             raycaster.setFromCamera(ndc, camera);
             const plane = new THREE.Plane();
             plane.setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()), ppState.dragStartPoint);
             const target = new THREE.Vector3();
             raycaster.ray.intersectPlane(plane, target);
             if (target) {
                 const deltaY = target.y - ppState.dragStartPoint.y;
                 const newHeight = Math.max(0.01, ppState.originalHeight + deltaY);
                 setPpState(prev => ({ ...prev, dragHeight: newHeight }));
                 updateShape(ppState.hoveredShapeId!, { height: newHeight });
             }
        } else {
            const intersect = e.intersections.find(i => i.object.userData?.isShape);
            if (intersect) {
                setPpState({ mode: 'top', hoveredShapeId: intersect.object.userData.id, dragStartPoint: null, originalHeight: 0 });
                document.body.style.cursor = 'ns-resize';
            } else {
                setPpState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
                document.body.style.cursor = 'default';
            }
        }
    }, [tool, ppState, shapes, camera, gl, updateShape]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || !ppState.hoveredShapeId || e.button !== 0) return;
        e.stopPropagation();
        const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
        if (shape) {
            setPpState(prev => ({ ...prev, dragStartPoint: e.point.clone(), originalHeight: shape.height }));
        }
    }, [tool, ppState.hoveredShapeId, shapes]);

    const handlePointerUp = useCallback(() => {
        if (ppState.dragStartPoint) setPpState(prev => ({ ...prev, dragStartPoint: null, dragHeight: undefined }));
    }, [ppState.dragStartPoint]);

    return { ppState, handlePointerMove, handlePointerDown, handlePointerUp };
};

const useRotateManager = () => {
    const { tool, selectedIds, updateShape, shapes } = useApp();
    const [rotateState, setRotateState] = useState<RotateState>({
        phase: 'hover', pivot: null, axis: null, startVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis: null
    });

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (tool !== ToolType.ROTATE || selectedIds.length === 0 || e.button !== 0) return;

        if (rotateState.phase === 'hover') {
            const pivot = e.point.clone();
            const initialTransforms: Record<string, { pos: THREE.Vector3, quat: THREE.Quaternion }> = {};
            selectedIds.forEach(id => {
                const shape = shapes.find(s => s.id === id);
                if (shape) {
                    initialTransforms[id] = { 
                        pos: new THREE.Vector3(...shape.position), 
                        quat: new THREE.Quaternion().setFromEuler(new THREE.Euler(...shape.rotation)) 
                    };
                }
            });
            setRotateState(prev => ({ ...prev, phase: 'set-start', pivot, initialTransforms }));
        } else if (rotateState.phase === 'set-start') {
            const startVec = e.point.clone().sub(rotateState.pivot!).normalize();
            setRotateState(prev => ({ ...prev, phase: 'rotating', startVector: startVec }));
        } else if (rotateState.phase === 'rotating') {
            setRotateState({ phase: 'hover', pivot: null, axis: null, startVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis: null });
        }
    }, [tool, selectedIds, rotateState, shapes]);

    const handleRotateMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.ROTATE || rotateState.phase !== 'rotating') return;
        const currentVec = e.point.clone().sub(rotateState.pivot!).normalize();
        let angle = rotateState.startVector!.angleTo(currentVec);
        const cross = new THREE.Vector3().crossVectors(rotateState.startVector!, currentVec);
        if (cross.y < 0) angle = -angle;

        selectedIds.forEach(id => {
            const init = rotateState.initialTransforms[id];
            if (!init) return;
            const relativePos = init.pos.clone().sub(rotateState.pivot!);
            relativePos.applyAxisAngle(new THREE.Vector3(0, 1, 0), angle);
            const newPos = rotateState.pivot!.clone().add(relativePos);
            const q = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), angle);
            const newQuat = init.quat.clone().multiply(q);
            const newEuler = new THREE.Euler().setFromQuaternion(newQuat);
            updateShape(id, { position: [newPos.x, newPos.y, newPos.z], rotation: [newEuler.x, newEuler.y, newEuler.z] });
        });
    }, [tool, rotateState, selectedIds, updateShape]);

    return { rotateState, handleClick, handleRotateMove };
};

const useDrawingManager = () => {
    const { tool, addShape, shapes } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [inferenceGuide, setInferenceGuide] = useState<InferenceGuide | null>(null);

    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        const intersect = e.intersections.find(i => i.object.userData?.isShape);
        const snap = getGeometrySnap(e.point, e.ray, shapes, drawPoints, SNAP_THRESHOLD, intersect);
        setCursorPos(snap.position);
        setSnapInfo(snap);
    }, [shapes, drawPoints]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        // Only draw on Left Click
        if (e.button !== 0) return;

        // Prevent drawing if we clicked on a Gizmo or other interactive element
        // (Handled by checking tool type mostly, but stopPropagation helps)

        if (![ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DIMENSION, ToolType.MEASURE].includes(tool)) return;

        e.stopPropagation();
        const p = snapInfo ? snapInfo.position : e.point;
        const newPoint = { x: p.x, y: 0, z: p.z };

        if (tool === ToolType.DRAW_LINE) {
            const newPoints = [...drawPoints, newPoint];
            setDrawPoints(newPoints);
            // Finish line if clicking back on start (roughly)
            if (drawPoints.length > 2 && snapInfo?.type === 'endpoint' && isSamePoint(newPoint, drawPoints[0])) {
                 addShape({ id: `poly-${Date.now()}`, type: 'solid', points: newPoints.slice(0, -1), height: 3, color: DEFAULT_COLOR, position: [0,0,0], rotation: [0,0,0], scale: [1,1,1], name: 'Poly', layerId: 'layer-structure' });
                 setDrawPoints([]);
            }
        } else if (tool === ToolType.DRAW_RECT) {
            if (drawPoints.length === 0) {
                setDrawPoints([newPoint]);
            } else {
                const start = drawPoints[0];
                const width = newPoint.x - start.x;
                const depth = newPoint.z - start.z;
                const pts = [{ x: 0, y: 0, z: 0 }, { x: width, y: 0, z: 0 }, { x: width, y: 0, z: depth }, { x: 0, y: 0, z: depth }];
                addShape({ id: `rect-${Date.now()}`, type: 'solid', points: pts, height: 0.1, color: DEFAULT_COLOR, position: [start.x, 0, start.z], rotation: [0,0,0], scale: [1,1,1], name: 'Rect', layerId: 'layer-structure' });
                setDrawPoints([]);
            }
        } else if (tool === ToolType.DRAW_CIRCLE) {
            if (drawPoints.length === 0) {
                setDrawPoints([newPoint]);
            } else {
                const center = drawPoints[0];
                const radius = Math.sqrt(Math.pow(newPoint.x - center.x, 2) + Math.pow(newPoint.z - center.z, 2));
                const pts = createCirclePoints(radius);
                addShape({ id: `circle-${Date.now()}`, type: 'solid', points: pts, height: 0.1, color: DEFAULT_COLOR, position: [center.x, 0, center.z], rotation: [0,0,0], scale: [1,1,1], name: 'Circle', layerId: 'layer-structure' });
                setDrawPoints([]);
            }
        }
    }, [tool, snapInfo, drawPoints, addShape]);

    return { 
        drawPoints, cursorPos, setCursorPos, snapInfo, setSnapInfo, inferenceGuide, setInferenceGuide, 
        handlePointerDown, handlePointerUp: () => {}, handleClick: handlePointerDown, handlePointerMove 
    };
};

const useBoxSelection = ({ onBoxChange }: { onBoxChange: (box: { left: number, top: number, width: number, height: number } | null) => void }) => {
    const { tool } = useApp();
    const { gl } = useThree();
    const [startPos, setStartPos] = useState<{x: number, y: number} | null>(null);

    useEffect(() => {
        if (tool !== ToolType.SELECT) return;
        const canvas = gl.domElement;
        const onDown = (e: PointerEvent) => {
            if (e.button !== 0 || e.ctrlKey) return;
            const rect = canvas.getBoundingClientRect();
            setStartPos({ x: e.clientX - rect.left, y: e.clientY - rect.top });
        };
        const onMove = (e: PointerEvent) => {
            if (!startPos) return;
            const rect = canvas.getBoundingClientRect();
            const currentX = e.clientX - rect.left;
            const currentY = e.clientY - rect.top;
            onBoxChange({ left: Math.min(startPos.x, currentX), top: Math.min(startPos.y, currentY), width: Math.abs(currentX - startPos.x), height: Math.abs(currentY - startPos.y) });
        };
        const onUp = () => {
            if (startPos) { onBoxChange(null); setStartPos(null); }
        };
        canvas.addEventListener('pointerdown', onDown);
        window.addEventListener('pointermove', onMove);
        window.addEventListener('pointerup', onUp);
        return () => {
            canvas.removeEventListener('pointerdown', onDown);
            window.removeEventListener('pointermove', onMove);
            window.removeEventListener('pointerup', onUp);
        };
    }, [tool, startPos, gl.domElement, onBoxChange]);

    return { onPointerDown: (_e?: any) => {} };
};

// --- Main Component ---

const EditorContent: React.FC<{ onSelectionBoxUpdate: (box: { left: number, top: number, width: number, height: number } | null) => void }> = ({ onSelectionBoxUpdate }) => {
  const { shapes, tool, selectedIds, selectShape, deselectAll, updateShapes, guideLines, currentView, setCurrentView } = useApp();
  const [alignmentLines, setAlignmentLines] = useState<AlignmentLine[]>([]);
  const shapeRefs = useRef<Record<string, THREE.Group | null>>({});
  const [isGizmoDragging, setIsGizmoDragging] = useState(false);

  const setShapeRef = useCallback((id: string, ref: THREE.Group | null) => { shapeRefs.current[id] = ref; }, []);

  const { ppState, handlePointerMove: handlePPMove, handlePointerDown: handlePPDown, handlePointerUp: handlePPUp } = usePushPullManager();
  const { rotateState, handleRotateMove, handleClick: handleRotateClick } = useRotateManager();
  const { drawPoints, cursorPos: drawCursorPos, snapInfo: drawSnapInfo, handlePointerDown: handleDrawDown, handlePointerMove: handleDrawMove, inferenceGuide } = useDrawingManager();

  const { onPointerDown: onBoxDown } = useBoxSelection({ onBoxChange: onSelectionBoxUpdate });

  const pushPullHandlers = useMemo(() => ({ handlePointerDown: handlePPDown, handlePointerUp: handlePPUp, handlePointerMove: handlePPMove }), [handlePPDown, handlePPUp, handlePPMove]);
  const drawingHandlers = useMemo(() => ({ handlePointerDown: handleDrawDown, handlePointerUp: () => {}, handleClick: () => {} }), [handleDrawDown]);
  const rotateHandlers = useMemo(() => ({ handleClick: handleRotateClick, handlePointerMove: handleRotateMove }), [handleRotateClick, handleRotateMove]);

  return (
    <>
        <ambientLight intensity={0.7} />
        <directionalLight position={[10, 20, 10]} intensity={1.2} castShadow shadow-mapSize={[2048, 2048]} />
        <Grid infiniteGrid fadeDistance={50} sectionColor="#cbd5e1" cellColor="#e2e8f0" sectionSize={1} cellSize={0.1} />

        <MemoizedOrbitControls tool={tool} />

        <group 
            onPointerDown={(e) => {
                if (tool === ToolType.ROTATE) handleRotateClick(e);
                else if (tool === ToolType.SELECT) { onBoxDown(e); deselectAll(); }
                else if (tool !== ToolType.PUSH_PULL) handleDrawDown(e);
            }} 
            onPointerUp={(e) => { if (tool === ToolType.PUSH_PULL) handlePPUp(); }}
            onPointerMove={(e) => { 
                if (tool === ToolType.PUSH_PULL) handlePPMove(e); 
                else if (tool === ToolType.ROTATE) handleRotateMove(e);
                else handleDrawMove(e);
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, -0.02, 0]} receiveShadow><planeGeometry args={[1000, 1000]} /><meshBasicMaterial visible={false} /></mesh>
        </group>

        <group>
          {shapes.map(shape => (
            <ShapeRenderer
              key={shape.id}
              shape={shape}
              isSelected={selectedIds.includes(shape.id)}
              pushPullState={ppState}
              pushPullHandlers={pushPullHandlers}
              drawingHandlers={drawingHandlers}
              rotateHandlers={rotateHandlers}
              setDraggingState={() => {}}
              onShapeRef={setShapeRef}
              shapeRefs={shapeRefs}
              setAlignmentLines={setAlignmentLines}
            />
          ))}
        </group>

        <InteractionLayer tool={tool} cursorPos={drawCursorPos} snapInfo={drawSnapInfo} drawPoints={drawPoints} inferenceGuide={inferenceGuide} drawingNormal={new THREE.Vector3(0,1,0)} />
        <AlignmentLinesRenderer lines={alignmentLines} />
        <GuideLinesRenderer lines={guideLines} />

        { !isGizmoDragging && <SelectionGizmo setDragging={setIsGizmoDragging} /> }
        { isGizmoDragging && <SelectionGizmo setDragging={setIsGizmoDragging} /> }

        <GizmoHelper alignment="bottom-left" margin={[80, 80]}><GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="white" /></GizmoHelper>
        <CameraHandler view={currentView} onFinished={() => setCurrentView(null)} />
    </>
  );
};

const Viewport: React.FC = () => {
  const { tool, deselectAll } = useApp();
  const [selectionBox, setSelectionBox] = useState<{ left: number, top: number, width: number, height: number } | null>(null);

  return (
    <div className="w-full h-full bg-slate-50 relative cursor-crosshair" onContextMenu={(e) => e.preventDefault()}>
      <Canvas shadows camera={{ position: [5, 5, 5], fov: 50 }} gl={{ preserveDrawingBuffer: true, antialias: true }} onPointerMissed={(e) => { if (tool === ToolType.SELECT && e.type === 'click' && !e.ctrlKey) { deselectAll(); } }}>
        <color attach="background" args={['#f8fafc']} />
        <EditorContent onSelectionBoxUpdate={setSelectionBox} />
      </Canvas>
      {selectionBox && (
        <div className="absolute border border-blue-500 bg-blue-500/20 pointer-events-none z-10" style={{ left: selectionBox.left, top: selectionBox.top, width: selectionBox.width, height: selectionBox.height }} />
      )}
    </div>
  );
};

export default Viewport;

