const ShapeRenderer: React.FC<ShapeRendererProps> = ({ shape, isSelected, pushPullState, pushPullHandlers, drawingHandlers, rotateHandlers, setDraggingState, onShapeRef }) => {
    const meshRef = useRef<THREE.Mesh>(null);
    const groupRef = useRef<THREE.Group>(null);
    const { tool, selectShape } = useApp();

    useEffect(() => {
        if (groupRef.current) onShapeRef(shape.id, groupRef.current);
        return () => onShapeRef(shape.id, null);
    }, [shape.id, onShapeRef]);

    const isPushPullMode = tool === ToolType.PUSH_PULL;

    // Calculate drag scale for push/pull preview
    let scaleY = 1;
    const isDraggingTop = pushPullState.mode === 'top' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) {
        scaleY = pushPullState.dragHeight / shape.height;
    }

    if (shape.type === 'dimension') return <DimensionShape shape={shape} isSelected={isSelected} onSelect={drawingHandlers.handleClick} />;

    if (shape.type === 'line') {
         const points = shape.points.map(p => new THREE.Vector3(p.x, p.y, p.z));
         return (
             <group 
                position={shape.position} rotation={shape.rotation} scale={shape.scale}
                onClick={(e) => { e.stopPropagation(); selectShape(shape.id, e.ctrlKey); }}
             >
                 <SimpleLine points={points} color={isSelected ? HIGHLIGHT_COLOR : shape.color} />
             </group>
         );
    }

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);
    const extrudeSettings = useMemo(() => ({ depth: shape.height, bevelEnabled: false }), [shape.height]);

    return (
        <group ref={groupRef} position={shape.position} rotation={shape.rotation} scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]}
            onPointerDown={(e) => {
                if (isPushPullMode) pushPullHandlers.handlePointerDown(e);
                else if (tool === ToolType.ROTATE) rotateHandlers.handleClick(e);
                else if (tool === ToolType.SELECT) { e.stopPropagation(); selectShape(shape.id, e.ctrlKey); }
                else drawingHandlers.handlePointerDown(e);
            }}
            onPointerMove={(e) => { if (isPushPullMode) pushPullHandlers.handlePointerMove(e); }}
            onPointerUp={(e) => { if (isPushPullMode) pushPullHandlers.handlePointerUp(); }}
        >
             <mesh ref={meshRef} rotation={[Math.PI / 2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, extrudeSettings]} />
                <meshStandardMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} transparent={shape.type === 'flat'} opacity={shape.type === 'flat' ? 0.5 : 1} />
             </mesh>
             <lineSegments rotation={[Math.PI / 2, 0, 0]}>
                <edgesGeometry args={[new THREE.ExtrudeGeometry(shape2D, extrudeSettings)]} />
                <lineBasicMaterial color={isSelected ? "white" : "black"} />
             </lineSegments>
        </group>
    );
};

