const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3; drawingNormal: THREE.Vector3 }> = ({ tool, points, cursorPos, drawingNormal }) => {
    const { formatValue } = useApp();
    if (points.length === 0) return null;

    const start = points[points.length - 1];
    const startVec = new THREE.Vector3(start.x, start.y, start.z);

    if (tool === ToolType.DRAW_LINE) {
        // Show full path history + current line
        const historyPoints = points.map(p => new THREE.Vector3(p.x, p.y, p.z));
        return (
            <group>
                <SimpleLine points={[...historyPoints, cursorPos]} color="#3b82f6" />
                <Billboard position={cursorPos}>
                    <Text fontSize={0.25} color="#3b82f6" anchorX="center" anchorY="bottom">{formatValue(startVec.distanceTo(cursorPos))}</Text>
                </Billboard>
            </group>
        );
    }

    if (tool === ToolType.DRAW_RECT && points.length === 1) {
        const { right, top } = getLocalBasis(drawingNormal);
        const diff = new THREE.Vector3().subVectors(cursorPos, startVec);
        const w = diff.dot(right);
        const h = diff.dot(top);

        const p1 = startVec;
        const p2 = startVec.clone().add(right.clone().multiplyScalar(w));
        const p3 = startVec.clone().add(right.clone().multiplyScalar(w)).add(top.clone().multiplyScalar(h));
        const p4 = startVec.clone().add(top.clone().multiplyScalar(h));

        return (
            <group>
                <SimpleLine points={[p1, p2, p3, p4, p1]} color="#3b82f6" />
                <Billboard position={p3}>
                    <Text fontSize={0.25} color="#3b82f6" anchorX="left" anchorY="bottom">{`${formatValue(Math.abs(w))} x ${formatValue(Math.abs(h))}`}</Text>
                </Billboard>
            </group>
        );
    }

    if (tool === ToolType.DRAW_CIRCLE && points.length === 1) {
        const radius = startVec.distanceTo(cursorPos);
        const circlePts = createCirclePoints(radius).map(p => new THREE.Vector3(p.x + startVec.x, p.y + startVec.y, p.z + startVec.z));
        return (
            <group>
                <SimpleLine points={circlePts} color="#3b82f6" />
                <SimpleLine points={[startVec, cursorPos]} color="#999" dashed />
                <Billboard position={cursorPos}>
                    <Text fontSize={0.25} color="#3b82f6" anchorX="center" anchorY="bottom">R: {formatValue(radius)}</Text>
                </Billboard>
            </group>
        );
    }

    return null;
};

